AMX_st.name='AMX'; 
AMX_st.lat=35+0.02/60+19/60^2;
AMX_st.lon=33+0.03/60+28/60^2;
AMX_st.alt=513;
AMX_st.env='Coast'; % 22 km to coast, not much sea salt, --> con?
AMX_st.footp='RB';
%%

% AMX_rd imported via impoart tool

AMX_rd_h.Properties.VariableNames{1}='Ba1_A';
AMX_rd_h.Properties.VariableNames{2}='Ba2_A';
AMX_rd_h.Properties.VariableNames{3}='Ba3_A';
