AMX_rd=retime(AMX_rd_h,'daily',@nanmedian);
names_rd=fieldnames(AMX_rd);
%%
datevec(AMX_rd.Time(1)) % begin in 2015 %[output:5160fee3]
datevec(AMX_rd.Time(end)) % end in 2025 %[output:182afd8e]
% % prctile(AMX_rd.U1_S11,[5 50 95]) % < 30%, ok. 
% % prctile(AMX_rd.U0_S11,[5 50 95])
plotFigControl(AMX_rd,AMX_st.name); %[output:39a574aa]
%%
% BP detection for scat coef and backscat

names_abs={'Ba1_A', 'Ba2_A', 'Ba3_A', 'Ba4_A', 'Ba5_A', 'Ba6_A', 'Ba7_A'};
break_AMX_abs_BP=change_point_analysis_Def(AMX_rd,names_abs,0.05,'AMX','Absorption MAAP'); %[output:1ac983fd] %[output:4eb69f7e] %[output:22be2878] %[output:4d646792] %[output:40245d0b] %[output:4a7fc149]
T_AMX_abs_BP=make_table_breakpoints_def(break_AMX_abs_BP); %[output:8c817f63] %[output:6dc8916a] %[output:2407c1e6]
%%
lambdaAE7=[370 470 520 590 660 880 950];
AMX_cal=compute_exp_D(AMX_rd,names_abs,lambdaAE7) %[output:303dcd26] %[output:43874752] %[output:2709546e] %[output:9a73ebcc] %[output:24ddd9c5] %[output:9eb256d3] %[output:93ac5f18] %[output:60dc737a] %[output:0b274ca7] %[output:8d5a375d] %[output:25fd1345] %[output:9d44d383] %[output:6451d87f] %[output:18e54bf3] %[output:2140f7bb] %[output:9254c6cf] %[output:14612477] %[output:72c473b9] %[output:4c963b00] %[output:8c7384c2] %[output:1ef1d601] %[output:2b55f068] %[output:8a21fd24] %[output:28d063e2] %[output:9d983ac9] %[output:92e78d73] %[output:2ab26019] %[output:90804b90] %[output:7be2c73d] %[output:672c3f5e] %[output:024db7b0] %[output:328c9108] %[output:1fe52240] %[output:3cff97eb] %[output:326b712e] %[output:722c469b] %[output:6adfb80b] %[output:8d3c20fe] %[output:09a21f81] %[output:39d667a9] %[output:08151503] %[output:71d7fa21] %[output:69c1c6c4] %[output:3ecd75fb] %[output:7f6a26e1] %[output:3c3e3fac] %[output:9a1ef289] %[output:074677de] %[output:121a4eb4] %[output:7203e2ec] %[output:086955d5] %[output:01a92115] %[output:7efb8339] %[output:0e79d720] %[output:9fc7ac96] %[output:8cd889bf] %[output:822c40a7]
